contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner, address distributor) public {
        require(newOwner != address(0), "zero owner not allowed for transfer");

        // initially the test contract is the owner (it deployed c)
        require(c.owner() == address(this), "test is initial owner");

        // owner transfers ownership (top-level state-changing call)
        c.transferOwnership(newOwner);
        address ownerAfterTransfer = c.owner();

        // as owner, setting the distributor succeeds
        bool okAsOwner;
        try c.setRewardDistributor(distributor) { okAsOwner = true; } catch { okAsOwner = false; }
        address distributorAfterSet = c.rewardDistributor();

        // renounce (top-level state-changing call)
        c.renounceOwnership();
        address ownerAfterRenounce = c.owner();

        // as non-owner, setting the distributor must revert
        bool revertedAsNonOwner;
        try c.setRewardDistributor(address(newOwner)) { revertedAsNonOwner = false; } catch { revertedAsNonOwner = true; }
        address distributorAfterRevert = c.rewardDistributor();

        assert(
            ownerAfterTransfer == newOwner &&
            okAsOwner &&
            distributorAfterSet == distributor &&
            ownerAfterRenounce == address(0) &&
            revertedAsNonOwner &&
            distributorAfterRevert == distributor
        );
    }

    receive() external payable {}
}

